import{_ as o,o as a,c as d,ag as c}from"./chunks/framework.DyxC4IQh.js";const u=JSON.parse('{"title":"方向键光标","description":"用 WASD 或 HJKL 把光标走到元素上再点，包括钻嵌套层级和四秒超时。","frontmatter":{"description":"用 WASD 或 HJKL 把光标走到元素上再点，包括钻嵌套层级和四秒超时。"},"headers":[],"relativePath":"guide/cursor.md","filePath":"guide/cursor.md","lastUpdated":1792367291000}'),t={name:"guide/cursor.md"};function r(i,e,n,p,h,s){return a(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="方向键光标" tabindex="-1">方向键光标 <a class="header-anchor" href="#方向键光标" aria-label="Permalink to &quot;方向键光标&quot;">​</a></h1><p>标签够用。目标密集成一片时，你要找的那一个往往要两个字母，眼睛得把满屏标签扫一遍；想把屏幕一排排看下去，逐个找标签同样麻烦。这两种情况下用方向键，把光标走到框上再点。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>按 <code>W</code> <code>A</code> <code>S</code> <code>D</code> 或 <code>H</code> <code>J</code> <code>K</code> <code>L</code>。屏幕上还没有光标时，方向键从屏幕中心起算：第一次按下，光标锚在中心那个方向上离你最近的可点击元素，周围画一圈绿框（半透明填充）。</p><p>此后按方向键在元素之间走，按点击键（hint 模式内固定 <code>Space</code>；模式外用设置里的光标点击键，默认 <code>Space</code>，可切 <code>Enter</code>）点它。hint 模式外按 <code>Esc</code> 清除光标；hint 模式内 <code>Esc</code> 退出的是 hint 模式，光标留在原地。</p><p>光标不依赖 hint 模式。不开 <code>F</code>，光靠方向键加一个点击键也能用完整套导航。</p><h2 id="走位按屏幕几何-不按控件树" tabindex="-1">走位按屏幕几何，不按控件树 <a class="header-anchor" href="#走位按屏幕几何-不按控件树" aria-label="Permalink to &quot;走位按屏幕几何，不按控件树&quot;">​</a></h2><p>候选判定看边缘是否错开：目标要在当前方向上跟你完全不重叠。往右走，左边缘落在你右边缘以内的都排除，正好贴着边界并排的算候选。列表一行行紧挨着、按钮一颗挨一颗，这种密排的界面照样走得住；同一排里压住你这半边的元素不会被当成右边那个。</p><p>打分取主轴上的边缘间距，再加上侧向间距的两倍。正对着你的邻居胜过斜上方的邻居，横向偏移过大的候选会被降权，所以长列表里按 <code>J</code> 落点会尽量保持在同一列。</p><p>8 像素一行的容差只用在贴标签的阅读顺序上。走位没有容差：压过来一个像素就不算这个方向的邻居，正好贴边则算。</p><h2 id="钻进容器里" tabindex="-1">钻进容器里 <a class="header-anchor" href="#钻进容器里" aria-label="Permalink to &quot;钻进容器里&quot;">​</a></h2><p>容器是嵌套的：可点击的容器内部还可以有可点击的元素，这些元素自成一层。结构还是递归的，一个节点本身可以是一张图。</p><p>方向键先在本级找邻居，所以一排卡片是从左到右挨着走的，不会被中途拐进某张卡片里。本级那个方向没有邻居，光标才钻进当前节点内部，落在子层里那个方向最远的一个元素上。设置页每一行靠的都是这一下：整行占满屏宽，右边没有邻居，按 <code>L</code> 进到行里，停在开关上。</p><p>钻进去之后接着按方向键，先在子层内部走。子层走到头，光标回浮到父容器；父容器那个方向还有邻居，就顺着它继续走。已经在顶层且那个方向没东西，原地不动。</p><h2 id="什么时候消失" tabindex="-1">什么时候消失 <a class="header-anchor" href="#什么时候消失" aria-label="Permalink to &quot;什么时候消失&quot;">​</a></h2><p>光标有 4 秒不活动超时。最后一次移动之后 4 秒内没有新操作，光标自动清除；这条判定在 hint 模式显示标签期间不执行，标签还挂着的时候，光标不会因为手停下来而被收走。超时检查跟着界面刷新走，约每 32 毫秒一次。这段时间里屏幕内容变了，光标会跟着重新锚定到节点当前位置；节点消失、不可见、或尺寸归零，光标立即清除。</p><p>刷新循环只在 hint 模式或光标存在时运行，退出 hint 模式时它被整个摘掉。所以在 hint 模式里走出光标、再按 <code>Esc</code> 退出，绿框会留在屏幕上：不走超时，也不跟随界面移动，直到你再按一次方向键把它接回去。</p><p>再按 <code>F</code> 进 hint 模式时，光标先被清掉。</p><h2 id="关掉一组方向键" tabindex="-1">关掉一组方向键 <a class="header-anchor" href="#关掉一组方向键" aria-label="Permalink to &quot;关掉一组方向键&quot;">​</a></h2><p>WASD 和 HJKL 各自可以独立关闭，见<a href="/vimact-site/guide/settings.html">应用设置</a>。关掉的那组，四个字母就还给标签字符集，屏幕上的标签会更短。</p><p>保留跟着开关走：WASD 开着，<code>w</code> <code>a</code> <code>s</code> <code>d</code> 就当方向键，标签里不会出现这四个字母；把 WASD 关掉，它们立刻还给标签，哪怕 HJKL 还开着。HJKL 同理。</p>',21)])])}const _=o(t,[["render",r]]);export{u as __pageData,_ as default};
